enum_val.ev_driverval:
userdict /pt_rotate known not {
userdict /pt_rotate true put
userdict /pt_beginpage systemdict /currentpagedevice get exec
 /BeginPage get put
userdict /pt_rotated_beginpage {
   0 systemdict /currentpagedevice get exec /PageSize get
   1 get translate -90 rotate
 userdict /pt_beginpage get exec
} bind put
% Report logical paper to document code; render on the transposed device.
userdict /currentpagedevice {
 systemdict /currentpagedevice get exec dup length dict copy
 dup dup /PageSize get aload pop exch 2 array astore
 /PageSize exch put
 dup /BeginPage userdict /pt_beginpage get put
} bind put
userdict /setpagedevice {
 dup length dict copy
 % Preserve page hooks, including updates which do not change PageSize.
 dup /BeginPage known {
  dup /BeginPage get userdict /pt_rotated_beginpage get ne {
   userdict /pt_beginpage 2 index /BeginPage get put
  } if
 } if
 dup /BeginPage userdict /pt_rotated_beginpage get put
 dup /PageSize known {
  dup dup /PageSize get aload pop exch 2 array astore
  /PageSize exch put
 } if
 systemdict /setpagedevice get exec
} bind put
<< /PageSize systemdict /currentpagedevice get exec /PageSize get >>
setpagedevice
} if

